def split_fields(text: str) -> list[str]:
    fields = []
    field = ""
    escaping = False
    for char in text:
        if escaping:
            if char != "," and char != "\\":
                raise ValueError
            field = field + char
            escaping = False
        elif char == "\\":
            escaping = True
        elif char == ",":
            fields.append(field)
            field = ""
        else:
            field = field + char
    if escaping:
        raise ValueError
    fields.append(field)
    return fields

